import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    points = []
    for _ in range(n):
        x = int(next(iterator))
        y = int(next(iterator))
        points.append((x, y))

    if n <= 2:
        print("success")
        return

    # Check if all points are collinear
    def is_collinear(pts):
        if len(pts) <= 2:
            return True
        x1, y1 = pts[0]
        x2, y2 = pts[1]
        dx = x2 - x1
        dy = y2 - y1
        for i in range(2, len(pts)):
            xi, yi = pts[i]
            if dx * (yi - y1) != dy * (xi - x1):
                return False
        return True

    if is_collinear(points):
        print("success")
        return

    # Try removing each point and check if the rest are collinear
    # If yes, then we can hit the removed point with one shot and the rest with another
    for i in range(n):
        subset = points[:i] + points[i+1:]
        if is_collinear(subset):
            print("success")
            return

    print("failure")

if __name__ == "__main__":
    solve()
